CREATE TABLE IF NOT EXISTS account_access (user_id TEXT PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE, role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')), status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')), monthly_limit INTEGER NOT NULL DEFAULT 100 CHECK(monthly_limit >= 0), last_active TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS invitations (email TEXT PRIMARY KEY, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','revoked')), expires_at TIMESTAMPTZ NOT NULL, created_by TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS workspaces (owner_id TEXT PRIMARY KEY REFERENCES "user"(id) ON DELETE CASCADE, revision INTEGER NOT NULL DEFAULT 0, meta JSONB NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS projects (owner_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, id TEXT NOT NULL, data JSONB NOT NULL, PRIMARY KEY(owner_id,id));
CREATE TABLE IF NOT EXISTS resumes (owner_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, id TEXT NOT NULL, data JSONB NOT NULL, PRIMARY KEY(owner_id,id));
CREATE TABLE IF NOT EXISTS resume_versions (owner_id TEXT NOT NULL, resume_id TEXT NOT NULL, id TEXT NOT NULL, data JSONB NOT NULL, PRIMARY KEY(owner_id,resume_id,id), FOREIGN KEY(owner_id,resume_id) REFERENCES resumes(owner_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS conversations (owner_id TEXT NOT NULL, resume_id TEXT NOT NULL, data JSONB NOT NULL, PRIMARY KEY(owner_id,resume_id), FOREIGN KEY(owner_id,resume_id) REFERENCES resumes(owner_id,id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS workspace_imports (owner_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, fingerprint TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), PRIMARY KEY(owner_id,fingerprint));
CREATE TABLE IF NOT EXISTS workspace_mutations (owner_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, mutation_id TEXT NOT NULL, revision INTEGER NOT NULL, PRIMARY KEY(owner_id,mutation_id));
CREATE TABLE IF NOT EXISTS sync_backups (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES "user"(id) ON DELETE CASCADE, revision INTEGER NOT NULL, data JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS admin_grants (session_id TEXT PRIMARY KEY REFERENCES session(id) ON DELETE CASCADE, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS app_limits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS model_connections (id TEXT NOT NULL, scope TEXT NOT NULL CHECK(scope IN ('platform','user')), owner_id TEXT NOT NULL, data JSONB NOT NULL, secret TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, monthly_limit INTEGER NOT NULL DEFAULT 1000 CHECK(monthly_limit >= 0), PRIMARY KEY(owner_id,id));
CREATE TABLE IF NOT EXISTS model_usage (id TEXT PRIMARY KEY, user_id TEXT REFERENCES "user"(id) ON DELETE SET NULL, model_id TEXT NOT NULL, model_name TEXT NOT NULL, source TEXT NOT NULL, status TEXT NOT NULL, duration_ms INTEGER NOT NULL DEFAULT 0, input_tokens INTEGER, output_tokens INTEGER, error_type TEXT, started_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS model_usage_period ON model_usage(user_id, started_at);
CREATE TABLE IF NOT EXISTS template_releases (id TEXT NOT NULL, version INTEGER NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL, design JSONB NOT NULL, state TEXT NOT NULL CHECK(state IN ('draft','published','retired')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), published_at TIMESTAMPTZ, PRIMARY KEY(id,version));
CREATE TABLE IF NOT EXISTS template_catalog (id TEXT PRIMARY KEY, published_version INTEGER, enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS audit_events (id TEXT PRIMARY KEY, actor_id TEXT, actor_email TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, before_value JSONB, after_value JSONB, reason TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS admin_bootstrap (id INTEGER PRIMARY KEY CHECK(id=1), token_hash TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL, consumed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS platform_settings (key TEXT PRIMARY KEY, data JSONB NOT NULL, secret TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL DEFAULT 0, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
